  const formatBRL = (v) =>
    Number(v || 0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

  const ingredientCost = (ing) => (ing.free ? 0 : Number(ing.price) || 0);

  const sortBySavedOrder = (items, savedOrder = []) => {
    const positions = new Map(savedOrder.map((id, index) => [id, index]));
    return [...items].sort((a, b) => {
      const positionA = positions.has(a.id) ? positions.get(a.id) : Number.MAX_SAFE_INTEGER;
      const positionB = positions.has(b.id) ? positions.get(b.id) : Number.MAX_SAFE_INTEGER;
      return positionA - positionB;
    });
  };

  const ingredientNameKey = (ing) => ing.name.trim().toLowerCase();
  const isFruit = (ing) => ing.type === "fruit" || FRUIT_NAMES.has(ingredientNameKey(ing));
  const normalIngredients = (ingredients) => ingredients.filter((ing) => !isFruit(ing) && !HIDDEN_OPTION_NAMES.has(ingredientNameKey(ing)));
  const getProductRule = (category, size) => {
    if (PRODUCT_RULES.cup[category]) return { ingredientLimit: PRODUCT_RULES.cup[category][size], fruitLimit: 0, toppingLimit: 1, cupSeparatedIngredients: size === 1000 };
    if (category === "tigela") return { ingredientLimit: PRODUCT_RULES.tigela[size], fruitLimit: 2, toppingLimit: 1, cupSeparatedIngredients: false };
    return { ingredientLimit: PRODUCT_RULES.barca[size], fruitLimit: 2, toppingLimit: 1, cupSeparatedIngredients: false };
  };
  const calculateProductPrice = ({ category, size, ingredients = [], fruits = [], additionalIngredients = [], topping = null }, prices) => {
    const rule = getProductRule(category, size);
    const basePrice = prices[category][size];
    const ingredientExtraCount = Math.max(0, ingredients.length - rule.ingredientLimit);
    const fruitExtraCount = Math.max(0, fruits.length - rule.fruitLimit);
    const ingredientAdditionalPrice = additionalIngredients.reduce((sum, ing) => sum + ingredientCost(ing), 0);
    const ingredientExcessPrice = ingredientExtraCount * PRODUCT_RULES.excessPrice;
    const fruitExcessPrice = fruitExtraCount * PRODUCT_RULES.excessPrice;
    return {
      basePrice,
      ingredientAdditionalPrice,
      ingredientExcessPrice,
      fruitExcessPrice,
      ingredientExtraCount,
      fruitExtraCount,
      total: basePrice + ingredientAdditionalPrice + ingredientExcessPrice + fruitExcessPrice,
      rule,
      topping,
    };
  };

  function itemLabel(category, size) {
    if (category === "tigela") return `Tigela ${size} ml`;
    if (category === "barca") return `Barca ${size === "grande" ? "Grande" : "Pequena"}`;
    return `${CATEGORY_LABEL[category]} ${size} ml`;
  }

  function unitPrice(item, prices) {
    if (Number.isFinite(item.finalPrice)) return item.finalPrice;
    return calculateProductPrice(item, prices).total;
  }

  /* ============================================================
    IDENTIFICAÇÃO DE INGREDIENTES/FRUTAS EXTRAS NA COMANDA
    Usa a mesma regra (rule.ingredientLimit / rule.fruitLimit) que já
    define os extras no resumo do pedido (ver step 3 do BuilderSection).
    Pedidos antigos sem essa informação continuam exibindo os itens
    normalmente, sem marcação de extra.
    ============================================================ */

  function getIngredientDisplayList(item) {
    const limit = item.calculation?.rule?.ingredientLimit;
    return (item.ingredients || []).map((ing, index) =>
      typeof limit === "number" && index >= limit ? `Ingrediente extra: ${ing.name}` : ing.name
    );
  }

  function getFruitDisplayList(item) {
    const limit = item.calculation?.rule?.fruitLimit;
    return (item.fruits || []).map((fruit, index) =>
      typeof limit === "number" && index >= limit ? `Fruta extra: ${fruit.name}` : fruit.name
    );
  }

  /* ============================================================
    CÓDIGO DO PEDIDO
    Somente números, sem prefixo. Timestamp (ms) + 3 dígitos
    aleatórios para reduzir risco de colisão em cliques quase
    simultâneos. Pedidos antigos no formato "ped-..." continuam
    funcionando normalmente (a busca é sempre por igualdade exata
    do id, sem depender do formato).
    ============================================================ */

  function generateOrderId() {
    return `${Date.now()}${Math.floor(100 + Math.random() * 900)}`;
  }

  function buildWhatsAppMessage(cart, customer, prices, subtotal, deliveryFee, orderId = null) {
    const lines = [];
    const isRetirada = customer.deliveryRegion === "Retirada";

    lines.push("Olá! Gostaria de fazer um pedido na Açaí Boca Roxa.");
    lines.push("");
    lines.push(isRetirada ? "🥡 Pedido para retirada:" : "🚗 Pedido para entrega:");
    lines.push("");
    lines.push("Pedido:");
    cart.forEach((item) => {
      lines.push(`${item.qty}x ${itemLabel(item.category, item.size)}`);
      if (item.ingredients?.length) {
        lines.push("Ingredientes:");
        getIngredientDisplayList(item).forEach((label) => lines.push(`- ${label}`));
      }
      if (item.fruits?.length) {
        lines.push("Frutas (copinho separado de 100 ml quando aplicável):");
        getFruitDisplayList(item).forEach((label) => lines.push(`- ${label}`));
      }
      if (item.topping) lines.push(`Cobertura: ${item.topping.name} (incluída)`);
      if (item.calculation?.ingredientExcessPrice) lines.push(`Ingredientes extras: ${formatBRL(item.calculation.ingredientExcessPrice)}`);
      if (item.calculation?.fruitExcessPrice) lines.push(`Frutas extras: ${formatBRL(item.calculation.fruitExcessPrice)}`);
      lines.push(`Subtotal do item: ${formatBRL(unitPrice(item, prices))}`);
    });
    const total = subtotal + deliveryFee;
    lines.push("");
    lines.push(`Subtotal dos produtos: ${formatBRL(subtotal)}`);
    if (isRetirada) {
      lines.push(`Taxa de entrega: Grátis (Retirada)`);
    } else {
      lines.push(`Taxa de entrega (${customer.deliveryRegion}): ${formatBRL(deliveryFee)}`);
    }
    lines.push(`Total: ${formatBRL(total)}`);
    lines.push("");
    lines.push(`Nome: ${customer.name || "-"}`);
    lines.push(`Endereço: ${isRetirada ? "Retirada no local" : (customer.address || "-")}`);
    lines.push(`Forma de pagamento: ${customer.payment || "-"}`);
    lines.push(`Observação: ${customer.note || "-"}`);
    if (orderId) {
      lines.push("");
      lines.push(`📋 Código do pedido: ${orderId}`);
      lines.push("Use este código para acompanhar o status do pedido no site.");
    }
    return lines.join("\n");
  }

