  function AddProductModal({ category, size, prices, ingredients, ingredientOrder, fruitOrder, onClose, onConfirm, onGoToCart }) {
    const [ings, setIngs] = useState([]);
    const [fruits, setFruits] = useState([]);
    const [topping, setTopping] = useState(TOPPING_OPTIONS[0]);
    const availableIngredients = sortBySavedOrder([...normalIngredients(ingredients), ...ADDITIONAL_OPTIONS.filter((option) => !ingredients.some((ing) => ingredientNameKey(ing) === ingredientNameKey(option)))], ingredientOrder);
    const availableFruits = sortBySavedOrder(FRUIT_OPTIONS, fruitOrder);
    const toggle = (ing) => setIngs((prev) => (prev.some((i) => i.id === ing.id) ? prev.filter((i) => i.id !== ing.id) : [...prev, ing]));
    const toggleFruit = (fruit) => setFruits((prev) => (prev.some((i) => i.id === fruit.id) ? prev.filter((i) => i.id !== fruit.id) : [...prev, fruit]));
    const calculation = calculateProductPrice({ category, size, ingredients: ings, fruits, topping }, prices);
    const label = itemLabel(category, size);

    return (
      <Modal
        title={label}
        onClose={onClose}
        footer={
          <div className="space-y-2">
            <button onClick={() => onConfirm({ ingredients: ings, fruits, topping, calculation })} className="w-full py-3 rounded-xl bg-purple-800 text-white font-semibold flex items-center justify-center gap-2 hover:bg-purple-900 active:scale-[.98] transition-all">
              <ShoppingCart size={16} /> Adicionar ao carrinho — {formatBRL(calculation.total)}
            </button>
            {onGoToCart && (
              <button onClick={() => { onConfirm({ ingredients: ings, fruits, topping, calculation }); onGoToCart(); }} className="w-full py-3 rounded-xl border border-purple-800 text-purple-800 font-semibold flex items-center justify-center gap-2 hover:bg-purple-50 active:scale-[.98] transition-all">
                Ir para o carrinho <ChevronRight size={16} />
              </button>
            )}
          </div>
        }
      >
        <p className="text-sm text-purple-500 mb-3">Ingredientes: {ings.length}/{calculation.rule.ingredientLimit}</p>
        <IngredientGrid ingredients={availableIngredients} selected={ings} onToggle={toggle} showPrices={false} includedLimit={calculation.rule.ingredientLimit} />
        <p className="text-sm font-semibold text-purple-800 mt-5 mb-2">Frutas</p>
        <p className="text-xs text-purple-500 mb-2">{calculation.rule.fruitLimit ? `Frutas: ${fruits.length}/${calculation.rule.fruitLimit}` : "Frutas: R$ 4,00 cada em copinho separado de 100 ml"}</p>
        <IngredientGrid ingredients={availableFruits} selected={fruits} onToggle={toggleFruit} showPrices={false} includedLimit={calculation.rule.fruitLimit} extraLabel="Fruta extra" />
        <p className="text-sm font-semibold text-purple-800 mt-5 mb-2">Cobertura incluída</p>
        <div className="grid grid-cols-2 gap-2">
          {TOPPING_OPTIONS.map((option) => <button key={option.id} onClick={() => setTopping(option)} className={`rounded-xl border px-3 py-2 text-left text-sm ${topping?.id === option.id ? "border-purple-700 bg-purple-50" : "border-purple-100"}`}>{option.name}{topping?.id === option.id && <Check size={14} className="inline ml-2 text-purple-700" />}</button>)}
        </div>
        <div className="mt-5 rounded-xl bg-purple-50 p-3 text-sm text-purple-800 space-y-1">
          {calculation.ingredientExtraCount > 0 && <p>{calculation.ingredientExtraCount} ingrediente(s) extra(s): +{formatBRL(calculation.ingredientExcessPrice)}</p>}
          {calculation.fruitExtraCount > 0 && <p>{calculation.fruitExtraCount} fruta(s) extra(s): +{formatBRL(calculation.fruitExcessPrice)}</p>}
          {size === 1000 && <p>3 ingredientes incluídos no copinho de 100 ml.</p>}
        </div>
      </Modal>
    );
  }

  /* ============================================================
    HEADER
    ============================================================ */

  function Header({ cartCount, onCartClick, onNav }) {
    const [open, setOpen] = useState(false);
    const links = [
      ["inicio", "Início"], ["cardapio", "Cardápio"], ["monte", "Monte seu Açaí"], ["acompanhar", "Acompanhar pedido"], ["sobre", "Sobre nós"], ["contato", "Contato"],
    ];
    return (
      <header className="sticky top-0 z-40 bg-white/90 backdrop-blur-md border-b border-purple-100">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 h-16 flex items-center">
          <Logo size={36} />
          <nav className="hidden lg:flex items-center gap-6">
            {links.map(([id, label]) => (
              <button key={id} onClick={() => onNav(id)} className="text-sm font-medium text-purple-800 hover:text-purple-950 transition-colors">{label}</button>
            ))}
          </nav>
          <div className="flex items-center gap-2 lg:ml-8">
            <button onClick={() => onNav("cardapio")} className="hidden sm:flex items-center gap-1.5 bg-purple-800 text-white text-sm font-semibold px-4 py-2.5 rounded-full hover:bg-purple-900 active:scale-95 transition-all">
              Fazer pedido <ChevronRight size={15} />
            </button>
            <button onClick={onCartClick} className="relative w-10 h-10 rounded-full flex items-center justify-center hover:bg-purple-50 text-purple-900">
              <ShoppingCart size={22} />
              {cartCount > 0 && <span className="absolute -top-1 -right-1 bg-pink-600 text-white text-[11px] font-bold w-5 h-5 rounded-full flex items-center justify-center">{cartCount}</span>}
            </button>
            <button onClick={() => onNav("acompanhar")} className="hidden sm:flex items-center gap-1.5 bg-purple-100 text-purple-800 text-sm font-semibold px-4 py-2.5 rounded-full hover:bg-purple-200 active:scale-95 transition-all">
              <ClipboardList size={15} /> Acompanhar pedido
            </button>
            <button onClick={() => setOpen((v) => !v)} className="lg:hidden w-10 h-10 rounded-full flex items-center justify-center hover:bg-purple-50 text-purple-900">
              {open ? <X size={22} /> : <Menu size={22} />}
            </button>
          </div>
        </div>
        {open && (
          <div className="lg:hidden border-t border-purple-100 px-4 py-3 flex flex-col gap-1 bg-white">
            {links.map(([id, label]) => (
              <button key={id} onClick={() => { onNav(id); setOpen(false); }} className="text-left py-2.5 px-2 rounded-lg text-purple-900 font-medium hover:bg-purple-50">{label}</button>
            ))}
          </div>
        )}
      </header>
    );
  }

  /* ============================================================
    HERO
    ============================================================ */

  function Hero({ onNav }) {
    return (
      <section id="inicio" className="relative overflow-hidden bg-gradient-to-br from-purple-950 via-purple-900 to-fuchsia-900">
        <div className="absolute -top-24 -right-24 w-96 h-96 rounded-full bg-purple-700/40 blur-3xl" />
        <div className="absolute bottom-0 left-0 w-72 h-72 rounded-full bg-pink-600/20 blur-3xl" />
        <div className="relative max-w-6xl mx-auto px-4 sm:px-6 py-16 sm:py-24 grid md:grid-cols-2 gap-12 items-center">
          <div className="text-center md:text-left">
            <h1 className="text-white font-black leading-[1.05] text-4xl sm:text-5xl md:text-6xl" style={{ fontFamily: "'Fraunces', serif" }}>
              Seu açaí do <span style={{ color: "#F7C948" }}>seu jeito.</span>
            </h1>
            <p className="mt-5 text-purple-100/90 text-lg max-w-md mx-auto md:mx-0">
              Açaí, cupuaçu e combinações deliciosas para deixar seu momento ainda melhor.
            </p>
            <div className="mt-6 inline-flex items-center gap-2 bg-white/10 backdrop-blur-sm px-4 py-2 rounded-full text-sm text-purple-100">
              <Clock size={16} />
              <span>🚗 Delivery: 13h às 18h</span>
            </div>
            <div className="mt-8 flex flex-col sm:flex-row gap-3 justify-center md:justify-start">
              <button onClick={() => onNav("cardapio")} className="bg-white text-purple-900 font-bold px-7 py-3.5 rounded-full hover:bg-purple-50 active:scale-95 transition-all">Ver cardápio</button>
              <button onClick={() => onNav("monte")} className="border border-purple-300/50 text-white font-semibold px-7 py-3.5 rounded-full hover:bg-white/10 active:scale-95 transition-all">Monte seu açaí</button>
            </div>
          </div>
          <div className="flex justify-center md:justify-end">
            <img src={PROMO_URI} alt="Açaí Boca Roxa — no copo ou na tigela" className="w-72 sm:w-96 rounded-[2rem] shadow-2xl shadow-purple-950/50" />
          </div>
        </div>
      </section>
    );
  }

  /* ============================================================
    CARDÁPIO
    ============================================================ */

  function MenuSection({ prices, onRequestAdd }) {
    const [cat, setCat] = useState(null);
    const sizes = cat ? SIZE_OPTIONS[cat] : [];

    return (
      <section id="cardapio" className="max-w-6xl mx-auto px-4 sm:px-6 py-16">
        <h2 className="text-3xl sm:text-4xl font-black text-purple-950 text-center" style={{ fontFamily: "'Fraunces', serif" }}>Nosso Cardápio</h2>
        <p className="text-center text-purple-500 mt-2 mb-8">Escolha a categoria e o tamanho ideal para você</p>

        {!cat ? (
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
            {CATEGORIES.map((c) => (
              <button key={c} onClick={() => setCat(c)} className="rounded-2xl border-2 border-purple-100 bg-white p-5 sm:p-6 text-center transition-all hover:border-purple-400 hover:bg-purple-50/50 hover:shadow-md hover:shadow-purple-900/5 active:scale-[.98]">
                <span className="block text-3xl sm:text-4xl mb-2.5">{CATEGORY_EMOJI[c]}</span>
                <span className="block font-bold text-purple-950">{CATEGORY_LABEL[c]}</span>
                <span className="mt-1 block text-xs font-medium text-purple-400">{SIZE_OPTIONS[c].length} opções</span>
              </button>
            ))}
          </div>
        ) : (
          <>
            <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
              <button onClick={() => setCat(null)} className="inline-flex items-center gap-1.5 text-sm font-semibold text-purple-700 hover:text-purple-950 transition-colors">
                <ArrowLeft size={15} /> Categorias
              </button>
              <div className="flex gap-2 overflow-x-auto pb-1 justify-start sm:justify-center">
                {CATEGORIES.map((c) => (
                  <Pill key={c} active={cat === c} onClick={() => setCat(c)}>{CATEGORY_LABEL[c]}</Pill>
                ))}
              </div>
            </div>

            {cat === "casadinho" && (
              <div className="flex items-center gap-3 mb-6 justify-center text-sm text-purple-600">
                <div className="flex h-5 w-24 rounded-full overflow-hidden border border-purple-200">
                  <div className="w-1/2 bg-purple-800" />
                  <div className="w-1/2 bg-amber-700" />
                </div>
                metade açaí, metade cupuaçu
              </div>
            )}

            <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
              {sizes.map((s) => (
                <SizeCard key={s} category={cat} size={s} prices={prices} onAdd={(size) => onRequestAdd(cat, size)} />
              ))}
            </div>
          </>
        )}
      </section>
    );
  }

  /* ============================================================
    ACOMPANHAR PEDIDO
    ============================================================ */

  function OrderTrackingSection({ onTrackOrder }) {
    const [orderId, setOrderId] = useState("");

    const handleSubmit = (e) => {
      e.preventDefault();
      if (orderId.trim()) {
        onTrackOrder(orderId.trim());
      }
    };

    return (
      <section id="acompanhar" className="max-w-6xl mx-auto px-4 sm:px-6 py-16">
        <h2 className="text-3xl sm:text-4xl font-black text-purple-950 text-center" style={{ fontFamily: "'Fraunces', serif" }}>Acompanhar pedido</h2>
        <p className="text-center text-purple-500 mt-2 mb-8">Digite o código do seu pedido para acompanhar o status</p>

        <div className="max-w-md mx-auto">
          <form onSubmit={handleSubmit} className="flex gap-2">
            <input
              type="text"
              value={orderId}
              onChange={(e) => setOrderId(e.target.value)}
              placeholder="Código do pedido (ex: 1789268877786)"
              className="flex-1 rounded-xl border border-purple-200 px-4 py-3 focus:outline-none focus:ring-2 focus:ring-purple-400"
            />
            <button
              type="submit"
              className="bg-purple-800 text-white font-bold px-6 py-3 rounded-xl hover:bg-purple-900 active:scale-95 transition-all"
            >
              Buscar
            </button>
          </form>
          <p className="mt-4 text-sm text-purple-500 text-center">
            O código do pedido foi enviado pelo WhatsApp após a confirmação.
          </p>
        </div>
      </section>
    );
  }

  /* ============================================================
    MONTE SEU AÇAÍ
    ============================================================ */

  function BuilderSection({ prices, ingredients, ingredientOrder, fruitOrder, addToCart, onOpenCart, prefill, clearPrefill }) {
    const [step, setStep] = useState(0);
    const [base, setBase] = useState(null);
    const [size, setSize] = useState(null);
    const [ings, setIngs] = useState([]);
    const [fruits, setFruits] = useState([]);
    const [topping, setTopping] = useState(TOPPING_OPTIONS[0]);
    const [showSummaryOptions, setShowSummaryOptions] = useState(false);

    useEffect(() => {
      if (prefill) {
        setBase(prefill.category);
        setSize(prefill.size);
        setIngs(prefill.ingredients);
        setFruits(prefill.fruits || []);
        setTopping(prefill.topping || null);
        setStep(2);
        clearPrefill();
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [prefill]);

    const sizes = base ? SIZE_OPTIONS[base] : [];
    const availableIngredients = sortBySavedOrder(ingredients.length > 0 ? [...normalIngredients(ingredients), ...ADDITIONAL_OPTIONS.filter((option) => !ingredients.some((ing) => ingredientNameKey(ing) === ingredientNameKey(option)))] : ADDITIONAL_OPTIONS, ingredientOrder);
    const availableFruits = sortBySavedOrder(FRUIT_OPTIONS, fruitOrder);
    const calculation = base && size ? calculateProductPrice({ category: base, size, ingredients: ings, fruits, topping }, prices) : null;

    const toggle = (ing) => setIngs((prev) => (prev.some((i) => i.id === ing.id) ? prev.filter((i) => i.id !== ing.id) : [...prev, ing]));
    const toggleFruit = (fruit) => setFruits((prev) => (prev.some((i) => i.id === fruit.id) ? prev.filter((i) => i.id !== fruit.id) : [...prev, fruit]));
    const reset = () => { setStep(0); setBase(null); setSize(null); setIngs([]); setFruits([]); setTopping(TOPPING_OPTIONS[0]); };
    const handleAdd = () => { addToCart({ category: base, size, ingredients: ings, fruits, topping, calculation }); reset(); };
    const steps = ["Base", "Tamanho", "Ingredientes", "Resumo"];

    return (
      <section id="monte" className="bg-purple-50/60 py-16">
        <div className="max-w-4xl mx-auto px-4 sm:px-6">
          <h2 className="text-3xl sm:text-4xl font-black text-purple-950 text-center" style={{ fontFamily: "'Fraunces', serif" }}>Monte seu Açaí</h2>
          <p className="text-center text-purple-500 mt-2 mb-8">Em poucos passos, do seu jeito</p>

          <div className="flex items-center justify-center gap-2 mb-8">
            {steps.map((label, i) => (
              <React.Fragment key={label}>
                <div className={`flex items-center gap-1.5 text-xs sm:text-sm font-semibold ${i <= step ? "text-purple-900" : "text-purple-300"}`}>
                  <span className={`w-6 h-6 rounded-full flex items-center justify-center text-[11px] ${i <= step ? "bg-purple-800 text-white" : "bg-purple-100"}`}>{i + 1}</span>
                  <span className="hidden sm:inline">{label}</span>
                </div>
                {i < steps.length - 1 && <div className={`w-6 sm:w-10 h-px ${i < step ? "bg-purple-700" : "bg-purple-200"}`} />}
              </React.Fragment>
            ))}
          </div>

          <div className="bg-white rounded-3xl shadow-sm border border-purple-100 p-5 sm:p-8">
            {step === 0 && (
              <div>
                <p className="font-semibold text-purple-950 mb-4">Escolha a base</p>
                <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
                  {CATEGORIES.map((c) => (
                    <button key={c} onClick={() => { setBase(c); setSize(null); setStep(1); }} className={`rounded-2xl border-2 p-5 text-center font-semibold transition-all ${base === c ? "border-purple-800 bg-purple-50" : "border-purple-100 hover:border-purple-300"}`}>
                      {CATEGORY_LABEL[c]}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {step === 1 && (
              <div>
                <p className="font-semibold text-purple-950 mb-4">Escolha o tamanho — {CATEGORY_LABEL[base]}</p>
                <div className="grid grid-cols-3 sm:grid-cols-5 gap-2.5">
                  {sizes.map((s) => (
                    <button key={s} onClick={() => { setSize(s); setStep(2); }} className={`rounded-xl border-2 py-3 text-sm font-semibold transition-all ${size === s ? "border-purple-800 bg-purple-50 text-purple-900" : "border-purple-100 hover:border-purple-300 text-purple-800"}`}>
                      {base === "acai" || base === "cupuacu" || base === "casadinho" ? `${s} ml` : itemLabel(base, s)}
                    </button>
                  ))}
                </div>
                <button onClick={() => setStep(0)} className="mt-5 text-sm text-purple-500 flex items-center gap-1 hover:text-purple-800"><ArrowLeft size={14} /> voltar</button>
              </div>
            )}

            {step === 2 && (
              <div>
                <p className="font-semibold text-purple-950 mb-4">Ingredientes: {ings.length}/{calculation?.rule.ingredientLimit || 0}</p>
                <IngredientGrid ingredients={availableIngredients} selected={ings} onToggle={toggle} showPrices={false} includedLimit={calculation?.rule.ingredientLimit || 0} />
                <p className="text-sm font-semibold text-purple-800 mt-5 mb-2">Frutas</p>
                <p className="text-xs text-purple-500 mb-2">{calculation?.rule.fruitLimit ? `Frutas: ${fruits.length}/${calculation.rule.fruitLimit}` : "Frutas: R$ 4,00 cada em copinho separado de 100 ml"}</p>
                <IngredientGrid ingredients={availableFruits} selected={fruits} onToggle={toggleFruit} showPrices={false} includedLimit={calculation?.rule.fruitLimit || 0} extraLabel="Fruta extra" />
                <p className="text-sm font-semibold text-purple-800 mt-5 mb-2">Cobertura incluída</p>
                <div className="grid grid-cols-2 gap-2">
                  {TOPPING_OPTIONS.map((option) => <button key={option.id} onClick={() => setTopping(option)} className={`rounded-xl border px-3 py-2 text-left text-sm ${topping?.id === option.id ? "border-purple-700 bg-purple-50" : "border-purple-100"}`}>{option.name}{topping?.id === option.id && <Check size={14} className="inline ml-2 text-purple-700" />}</button>)}
                </div>
                <div className="mt-4 text-sm text-purple-700 space-y-1">
                  {calculation?.ingredientExtraCount > 0 && <p>{calculation.ingredientExtraCount} ingrediente(s) extra(s): +{formatBRL(calculation.ingredientExcessPrice)}</p>}
                  {calculation?.fruitExtraCount > 0 && <p>{calculation.fruitExtraCount} fruta(s) extra(s): +{formatBRL(calculation.fruitExcessPrice)}</p>}
                  {size === 1000 && <p>3 ingredientes incluídos no copinho de 100 ml.</p>}
                </div>
                {showSummaryOptions && (
                  <div className="fixed inset-0 z-40" onClick={() => setShowSummaryOptions(false)} />
                )}
                <div className="relative flex items-center justify-between mt-6 gap-3">
                  <button onClick={() => setStep(1)} className="text-sm text-purple-500 flex items-center gap-1 hover:text-purple-800"><ArrowLeft size={14} /> voltar</button>
                  <div className="relative">
                    <button onClick={() => setShowSummaryOptions((v) => !v)} className="bg-purple-800 text-white font-semibold px-6 py-2.5 rounded-full hover:bg-purple-900">Ver resumo</button>
                    {showSummaryOptions && (
                      <div className="absolute bottom-full mb-2 right-0 bg-white rounded-lg shadow-lg border border-purple-200 p-2 z-50 min-w-[200px]">
                        <button onClick={() => {
                          setShowSummaryOptions(false);
                          if (base && size) {
                            addToCart({ category: base, size, ingredients: ings, fruits, topping, calculation });
                          }
                        }} className="w-full text-left px-3 py-2 text-sm text-purple-700 hover:bg-purple-50 rounded">
                          Adicionar ao carrinho
                        </button>
                        <button onClick={() => {
                          setShowSummaryOptions(false);
                          if (base && size) {
                            addToCart({ category: base, size, ingredients: ings, fruits, topping, calculation });
                            onOpenCart();
                          }
                        }} className="w-full text-left px-3 py-2 text-sm text-purple-700 hover:bg-purple-50 rounded">
                          Ir para o carrinho
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}

            {step === 3 && (
              <div>
                <p className="font-semibold text-purple-950 mb-4">Resumo do seu açaí</p>
                <div className="rounded-2xl bg-purple-50 p-5">
                  <div className="flex justify-between text-purple-950 font-semibold">
                    <span>{itemLabel(base, size)}</span>
                      <span>{formatBRL(calculation.basePrice)}</span>
                  </div>
                  {ings.length > 0 && (
                    <ul className="mt-3 space-y-1 text-sm text-purple-700">
                      {ings.map((i, index) => (
                        <li key={i.id} className="flex justify-between"><span>{i.name}</span><span>{index >= calculation.rule.ingredientLimit ? `Ingrediente extra +${formatBRL(PRODUCT_RULES.excessPrice)}` : "Incluído"}</span></li>
                      ))}
                    </ul>
                  )}
                  {fruits.length > 0 && <div className="mt-3 text-sm text-purple-700"><p className="font-semibold">Frutas</p><ul>{fruits.map((fruit, index) => <li key={fruit.id}>{fruit.name} {index >= calculation.rule.fruitLimit ? `— Fruta extra +${formatBRL(PRODUCT_RULES.excessPrice)}` : "— Incluída"}</li>)}</ul></div>}
                  {topping && <p className="mt-3 text-sm text-purple-700"><strong>Cobertura:</strong> {topping.name} (incluída)</p>}
                  {calculation.ingredientExcessPrice > 0 && <p className="mt-2 text-sm text-purple-700">Ingredientes extras: +{formatBRL(calculation.ingredientExcessPrice)}</p>}
                  {calculation.rule.cupSeparatedIngredients && <p className="mt-2 text-xs text-purple-500">Ingredientes em copinho separado de 100 ml.</p>}
                  <div className="border-t border-purple-200 mt-4 pt-3 flex justify-between font-bold text-purple-950 text-lg">
                    <span>Total do item</span><span>{formatBRL(calculation.total)}</span>
                  </div>
                </div>
                <div className="flex items-center justify-between mt-6">
                  <button onClick={() => setStep(2)} className="text-sm text-purple-500 flex items-center gap-1 hover:text-purple-800"><ArrowLeft size={14} /> voltar</button>
                  <button onClick={handleAdd} className="bg-purple-800 text-white font-semibold px-6 py-2.5 rounded-full hover:bg-purple-900 flex items-center gap-2"><ShoppingCart size={16} /> Adicionar ao carrinho</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </section>
    );
  }

  /* ============================================================
    CARRINHO (drawer)
    ============================================================ */

  function CartDrawer({ cart, prices, onClose, onQty, onRemove, onEdit, onCheckout }) {
    const total = cart.reduce((s, i) => s + unitPrice(i, prices) * i.qty, 0);
    return (
      <div className="fixed inset-0 z-50 flex justify-end">
        <div className="absolute inset-0 bg-purple-950/50" onClick={onClose} />
        <div className="relative bg-white w-full sm:w-[420px] h-full flex flex-col shadow-2xl">
          <div className="flex items-center justify-between px-5 py-4 border-b border-purple-50">
            <h3 className="font-bold text-lg text-purple-950" style={{ fontFamily: "'Fraunces', serif" }}>Seu pedido</h3>
            <button onClick={onClose} className="w-8 h-8 rounded-full flex items-center justify-center hover:bg-purple-50 text-purple-700"><X size={18} /></button>
          </div>

          <div className="flex-1 overflow-y-auto px-5 py-4">
            {cart.length === 0 ? (
              <p className="text-purple-400 text-center mt-10">Seu carrinho está vazio.</p>
            ) : (
              <div className="space-y-4">
                {cart.map((item) => (
                  <div key={item.id} className="border border-purple-100 rounded-2xl p-4">
                    <div className="flex justify-between items-start gap-2">
                      <div>
                        <p className="font-semibold text-purple-950">{itemLabel(item.category, item.size)}</p>
                        {item.ingredients.length > 0 && <p className="text-xs text-purple-500 mt-0.5">{item.ingredients.map((i) => i.name).join(", ")}</p>}
                        {item.fruits?.length > 0 && <p className="text-xs text-purple-500 mt-0.5">Frutas: {item.fruits.map((fruit) => fruit.name).join(", ")}</p>}
                        {item.topping && <p className="text-xs text-purple-500 mt-0.5">Cobertura: {item.topping.name}</p>}
                      </div>
                      <div className="flex gap-1 shrink-0">
                        <button onClick={() => onEdit(item)} className="w-7 h-7 rounded-full flex items-center justify-center hover:bg-purple-50 text-purple-500"><Pencil size={14} /></button>
                        <button onClick={() => onRemove(item.id)} className="w-7 h-7 rounded-full flex items-center justify-center hover:bg-pink-50 text-pink-500"><Trash2 size={14} /></button>
                      </div>
                    </div>
                    <div className="flex items-center justify-between mt-3">
                      <div className="flex items-center gap-3 border border-purple-100 rounded-full px-2 py-1">
                        <button onClick={() => onQty(item.id, -1)} className="w-6 h-6 flex items-center justify-center text-purple-700"><Minus size={14} /></button>
                        <span className="font-semibold text-sm w-4 text-center">{item.qty}</span>
                        <button onClick={() => onQty(item.id, 1)} className="w-6 h-6 flex items-center justify-center text-purple-700"><Plus size={14} /></button>
                      </div>
                      <p className="font-bold text-purple-950">{formatBRL(unitPrice(item, prices) * item.qty)}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {cart.length > 0 && (
            <div className="border-t border-purple-50 px-5 py-4 space-y-3">
              <div className="flex justify-between text-purple-950"><span className="text-purple-500">Subtotal</span><span className="font-semibold">{formatBRL(total)}</span></div>
              <div className="flex justify-between text-lg font-bold text-purple-950"><span>Total</span><span>{formatBRL(total)}</span></div>
              <button onClick={onCheckout} className="w-full py-3.5 rounded-xl bg-purple-800 text-white font-bold hover:bg-purple-900 active:scale-[.98] transition-all">Finalizar pedido</button>
            </div>
          )}
        </div>
      </div>
    );
  }

