/* ============================================================
   APP
   ============================================================ */

let _id = 1;
const nextId = () => _id++;

export default function App() {
  const [config, setConfig] = useState(DEFAULT_CONFIG);
  const [prices, setPrices] = useState(DEFAULT_PRICES);
  const [ingredients, setIngredients] = useState(DEFAULT_INGREDIENTS);
  const [orders, setOrders] = useState([]);
  const [ordersLoaded, setOrdersLoaded] = useState(false);

  const [cart, setCart] = useState([]);
  const [cartOpen, setCartOpen] = useState(false);
  const [checkoutOpen, setCheckoutOpen] = useState(false);
  const [addModal, setAddModal] = useState(null);
  const [builderPrefill, setBuilderPrefill] = useState(null);
  const [sentBanner, setSentBanner] = useState(false);
  const [orderTrackingOpen, setOrderTrackingOpen] = useState(false);
  const [trackingOrderId, setTrackingOrderId] = useState(null);
  const [soundEnabled, setSoundEnabled] = useState(() => localStorage.getItem("acai_boca_roxa_admin_sound_enabled") !== "false");
  const [newOrderAlert, setNewOrderAlert] = useState(false);
  const knownOrderIds = useRef(new Set());
  const soundEnabledRef = useRef(soundEnabled);
  const [currentTime, setCurrentTime] = useState(() => new Date());
  const deliveryStatus = getDeliveryStatus(config, currentTime);

  useEffect(() => {
    const timer = window.setInterval(() => setCurrentTime(new Date()), 30000);
    return () => window.clearInterval(timer);
  }, []);

  const getView = () => (window.location.pathname === "/gestao-abr7k2" ? "admin" : "site");
  const [view, setView] = useState(getView());
  const [adminAuthed, setAdminAuthed] = useState(false);
  const [authLoading, setAuthLoading] = useState(true);

  useEffect(() => {
  const checkSession = async () => {
    const { data } = await supabase.auth.getSession();

    setAdminAuthed(!!data.session);
    setAuthLoading(false);
  };

  checkSession();

  const { data: listener } = supabase.auth.onAuthStateChange(
    (_event, session) => {
      setAdminAuthed(!!session);
    }
  );

  return () => {
    listener.subscription.unsubscribe();
  };
}, []);

useEffect(() => {
  (async () => {
    const { data: configRow, error: configError } = await supabase
      .from("site_config")
      .select("data")
      .eq("id", "main")
      .single();

    if (!configError && configRow?.data) {
      setConfig({ ...DEFAULT_CONFIG, ...configRow.data });
    }

    const { data: pricesRow, error: pricesError } = await supabase
      .from("site_prices")
      .select("data")
      .eq("id", "main")
      .single();

    if (!pricesError && pricesRow?.data) {
      setPrices(pricesRow.data);
    }

    const { data: ingredientsRow, error: ingredientsError } = await supabase
      .from("site_ingredients")
      .select("data")
      .eq("id", "main")
      .single();

    if (!ingredientsError && ingredientsRow?.data) {
      setIngredients(ingredientsRow.data);
    } else {
      setIngredients(DEFAULT_INGREDIENTS);
    }

    const { data: ordersRows, error: ordersError } = await supabase
      .from("site_orders")
      .select("*")
      .order("created_at", { ascending: false });

    if (!ordersError && ordersRows) {
      const loadedOrders = ordersRows.map(mapOrderRow);
      loadedOrders.forEach((order) => knownOrderIds.current.add(order.id));
      setOrders(loadedOrders);
    } else {
      setOrders([]);
    }
    setOrdersLoaded(true);
  })();
}, []);

useEffect(() => {
  if (view !== "admin" || !adminAuthed || !ordersLoaded) return undefined;

  const channel = supabase
    .channel("site-orders-admin-realtime")
    .on(
      "postgres_changes",
      { event: "INSERT", schema: "public", table: "site_orders" },
      (payload) => {
        const order = mapOrderRow(payload.new);
        if (knownOrderIds.current.has(order.id)) return;
        knownOrderIds.current.add(order.id);
        setOrders((prev) => (prev.some((item) => item.id === order.id) ? prev : [order, ...prev]));
        setNewOrderAlert(true);
        if (soundEnabledRef.current) playNewOrderSound();
        window.setTimeout(() => setNewOrderAlert(false), 5000);
      }
    )
    .on(
      "postgres_changes",
      { event: "UPDATE", schema: "public", table: "site_orders" },
      (payload) => {
        const order = mapOrderRow(payload.new);
        setOrders((prev) => prev.map((item) => (item.id === order.id ? { ...item, ...order } : item)));
      }
    )
    .subscribe((status, error) => {
      if (status === "CHANNEL_ERROR" || status === "TIMED_OUT") {
        console.error("ERRO NO REALTIME DE PEDIDOS:", error || status);
      }
    });

  return () => {
    supabase.removeChannel(channel);
  };
}, [view, adminAuthed, ordersLoaded]);

  const toggleAdminSound = async () => {
    const nextEnabled = !soundEnabled;

    if (nextEnabled) {
      // Tenta inicializar o AudioContext quando o usuário ativa o som
      const context = initializeAudioContext();
      if (context && context.state === "suspended") {
        try {
          await context.resume();
        } catch (error) {
          console.error("Erro ao resumir AudioContext:", error);
        }
      }
    }

    soundEnabledRef.current = nextEnabled;
    setSoundEnabled(nextEnabled);
    localStorage.setItem("acai_boca_roxa_admin_sound_enabled", String(nextEnabled));

    if (nextEnabled) {
  await playNewOrderSound();
}
  };

  const scrollTo = (id) => document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "start" });

  const addToCart = ({ category, size, ingredients: ings, fruits = [], topping = null, calculation }) => {
    const itemCalculation = calculation || calculateProductPrice({ category, size, ingredients: ings, fruits, topping }, prices);
    setCart((prev) => [...prev, { id: nextId(), category, size, ingredients: ings, fruits, topping, calculation: itemCalculation, finalPrice: itemCalculation.total, qty: 1 }]);
  };
  const changeQty = (id, delta) => setCart((prev) => prev.map((i) => (i.id === id ? { ...i, qty: Math.max(1, i.qty + delta) } : i)));
  const removeItem = (id) => setCart((prev) => prev.filter((i) => i.id !== id));
  const editItem = (item) => {
    removeItem(item.id);
    setCartOpen(false);
    setBuilderPrefill({ category: item.category, size: item.size, ingredients: item.ingredients, fruits: item.fruits, topping: item.topping });
    setTimeout(() => scrollTo("monte"), 100);
  };
  const cartCount = cart.reduce((s, i) => s + i.qty, 0);

  const handleOrderSent = async (customer, subtotal, deliveryFee, orderType = "delivery", orderId) => {
    if (!customer.payment) {
      return { ok: false, message: "Selecione uma forma de pagamento para continuar." };
    }

    const { data: latestConfigRow, error: latestConfigError } = await supabase
      .from("site_config")
      .select("data")
      .eq("id", "main")
      .single();
    if (latestConfigError || !latestConfigRow?.data) {
      return { ok: false, message: "Não foi possível verificar o status do delivery. Tente novamente." };
    }
    const latestConfig = { ...DEFAULT_CONFIG, ...latestConfigRow.data };
    const latestDeliveryStatus = getDeliveryStatus(latestConfig);

    if (orderType === "delivery" && !latestDeliveryStatus.open) {
      return {
        ok: false,
        message: latestDeliveryStatus.reason === "horario"
          ? "Delivery fechado pelo horário. Funcionamos das 13h às 18h."
          : "Delivery fechado no momento. No momento não estamos aceitando novos pedidos.",
      };
    }

    const deliveryRegion = orderType === "retirada" ? "Retirada" : customer.deliveryRegion;
    const finalDeliveryFee = orderType === "retirada" ? 0 : deliveryFee;

    const order = {
      id: orderId || generateOrderId(),
      createdAt: new Date().toISOString(),
      customer: {
        ...customer,
        address: orderType === "retirada" ? "Retirada no local" : customer.address,
        note: orderType === "retirada" ? `Pedido retirada - ${customer.note || ""}` : customer.note,
      },
      items: cart,
      subtotal,
      deliveryRegion,
      deliveryFee: finalDeliveryFee,
      paymentMethod: customer.payment,
      total: subtotal + finalDeliveryFee,
      orderSource: orderType === "retirada" ? "retirada" : "delivery",
      status: "novo",
    };

    const { error } = await supabase
      .from("site_orders")
      .insert({
        id: order.id,
        created_at: order.createdAt,
        customer: order.customer,
        items: order.items,
        subtotal: order.subtotal,
        delivery_region: order.deliveryRegion,
        delivery_fee: order.deliveryFee,
        payment_method: order.customer.payment,
        order_source: order.orderSource,
        total: order.total,
        status: order.status,
      });

    if (error) {
      return { ok: false, message: "Não foi possível salvar o pedido. Tente novamente." };
    }

    // Limpa o carrinho e abre o modal de acompanhamento
    setCart([]);
    setTrackingOrderId(order.id);
    setOrderTrackingOpen(true);

    return { ok: true, orderId: order.id };
  };

  const handleTrackOrder = (orderId) => {
    setTrackingOrderId(orderId);
    setOrderTrackingOpen(true);
  };

  if (view === "admin") {
  if (authLoading) {
    return (
      <div className="min-h-screen bg-purple-50 flex items-center justify-center">
        <p className="text-purple-800 font-semibold">
          Verificando acesso...
        </p>
      </div>
    );
  }

  if (!adminAuthed) {
    return <AdminLogin onSuccess={() => setAdminAuthed(true)} />;
  }
    return (
      <div style={{ fontFamily: "'Manrope', sans-serif" }}>
        <style>{`@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400..900&family=Manrope:wght@400;500;600;700;800&display=swap');`}</style>
        <AdminPanel config={config} setConfig={setConfig} prices={prices} setPrices={setPrices} ingredients={ingredients} setIngredients={setIngredients} orders={orders} setOrders={setOrders} soundEnabled={soundEnabled} onToggleSound={toggleAdminSound} newOrderAlert={newOrderAlert} />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white" style={{ fontFamily: "'Manrope', sans-serif" }}>
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400..900&family=Manrope:wght@400;500;600;700;800&display=swap');`}</style>

      <Header cartCount={cartCount} onCartClick={() => setCartOpen(true)} onNav={scrollTo} />
      <Hero onNav={scrollTo} />
      <MenuSection prices={prices} onRequestAdd={(category, size) => setAddModal({ category, size })} />
      <BuilderSection prices={prices} ingredients={ingredients} ingredientOrder={config.ingredient_order} fruitOrder={config.fruit_order} addToCart={addToCart} onOpenCart={() => setCartOpen(true)} prefill={builderPrefill} clearPrefill={() => setBuilderPrefill(null)} />
      <OrderTrackingSection onTrackOrder={handleTrackOrder} />
      <About />
      <Contact config={config} />
      <Footer config={config} onNav={scrollTo} />

      {cartCount > 0 && !cartOpen && (
        <button onClick={() => setCartOpen(true)} className="fixed bottom-5 right-5 sm:hidden z-30 bg-purple-800 text-white rounded-full pl-4 pr-5 py-3.5 shadow-lg shadow-purple-900/30 flex items-center gap-2 font-semibold active:scale-95 transition-all">
          <ShoppingCart size={18} /> {cartCount}
        </button>
      )}

      {addModal && (
        <AddProductModal
          category={addModal.category} size={addModal.size} prices={prices} ingredients={ingredients} ingredientOrder={config.ingredient_order} fruitOrder={config.fruit_order}
          onClose={() => setAddModal(null)}
          onConfirm={(selection) => { addToCart({ category: addModal.category, size: addModal.size, ...selection }); setAddModal(null); }}
          onGoToCart={() => setCartOpen(true)}
        />
      )}

      {cartOpen && (
        <CartDrawer cart={cart} prices={prices} onClose={() => setCartOpen(false)} onQty={changeQty} onRemove={removeItem} onEdit={editItem} onCheckout={() => { setCartOpen(false); setCheckoutOpen(true); }} />
      )}

      {checkoutOpen && (
        <CheckoutModal cart={cart} prices={prices} config={config} deliveryStatus={deliveryStatus} onClose={() => setCheckoutOpen(false)} onSent={handleOrderSent} />
      )}

      {orderTrackingOpen && trackingOrderId && (
        <OrderTrackingModal
          orderId={trackingOrderId}
          onClose={() => setOrderTrackingOpen(false)}
        />
      )}

      {sentBanner && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-50 bg-purple-900 text-white px-5 py-3 rounded-full shadow-lg text-sm font-semibold flex items-center gap-2">
          <Check size={16} /> Pedido enviado com sucesso! Acompanhe o status do seu pedido.
        </div>
      )}
    </div>
  );
}
